package main

import (
	"context"
	"flag"
	"log"
	"os"
	"os/signal"
	"syscall"
	"time"

	"kafka-mcp/kafka"
	appmcp "kafka-mcp/mcp"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	// Configure default logger to write to Stderr.
	// Since MCP uses StdioTransport (stdin/stdout) for JSON-RPC communication,
	// writing any application logs or outputs to stdout will corrupt the stream.
	log.SetOutput(os.Stderr)
	log.SetPrefix("[KAFKA-MCP] ")
	log.SetFlags(log.LstdFlags | log.Lshortfile)

	brokerAddr := flag.String("broker", "localhost:9092", "Kafka bootstrap servers address")
	devMode := flag.Bool("dev", false, "Enable development mode (automatically starts mock producer)")
	mockOnly := flag.Bool("mock-only", false, "Publish 100 mock historical ticks to Kafka and exit immediately")
	flag.Parse()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Handle OS shutdown signals gracefully
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigChan
		log.Println("Received termination signal. Initiating graceful shutdown...")
		cancel()
	}()

	// 1. If mock-only flag is set, generate and publish 100 items, then exit.
	if *mockOnly {
		producer := kafka.NewProducer(*brokerAddr)
		mockData := kafka.GenerateMockData()
		err := producer.PublishMockData(ctx, mockData)
		if err != nil {
			log.Fatalf("Error publishing mock data: %v\n", err)
		}
		log.Println("Mock data published successfully. Exiting.")
		return
	}

	// 2. Initialize MCP server which manages cache
	mcpServer := appmcp.NewMCPServer()
	server := mcpServer.Server

	// 3. Initialize Kafka consumer
	// Updates the MCP Server cache when a message arrives
	topics := []string{"crypto-prices", "stock-ticker"}
	consumer := kafka.NewConsumer(*brokerAddr, "mcp-ticker-group", topics, func(msg kafka.TickerMessage) {
		mcpServer.UpdateCache(msg.Symbol, msg.Price, msg.Volume)
	})

	// Start consumer in a background goroutine
	go func() {
		log.Println("Starting Kafka consumer goroutine...")
		if err := consumer.Start(ctx); err != nil {
			log.Printf("Consumer exited with error: %v\n", err)
			cancel() // cancel context to stop server if consumer fails fatally
		}
	}()

	// 4. In dev mode, spin up mock production
	if *devMode {
		producer := kafka.NewProducer(*brokerAddr)

		// Run initial bootstrap data in background
		go func() {
			time.Sleep(1 * time.Second) // wait a moment for broker connection
			mockData := kafka.GenerateMockData()
			if err := producer.PublishMockData(ctx, mockData); err != nil {
				log.Printf("Dev Mode: Failed to publish initial mock data: %v\n", err)
			}
		}()

		// Start continuous mock generation in background (e.g. update every 800ms)
		go func() {
			time.Sleep(2 * time.Second)
			if err := producer.StartContinuousProduction(ctx, 800*time.Millisecond); err != nil {
				log.Printf("Dev Mode: Continuous producer exited with error: %v\n", err)
			}
		}()
	}

	// 5. Start MCP Server
	// This blocks until the transport is closed or context cancelled
	log.Println("Starting MCP server on STDIO transport...")
	// Run server on stdio transport
	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
		log.Fatal(err)
	}

	log.Println("Kafka MCP Server shutdown complete.")
}
